export interface AlignOpts {
  /** Score for matching characters */
  match: number;
  /** Score for mismatched characters */
  mismatch: number;
  /** Penalty for a gap (insertion or deletion) */
  gap: number;
}

export interface AlignmentResult {
  /** Final alignment score */
  score: number;
  /** Aligned version of `a` with gap characters ('-') inserted */
  alignedA: string;
  /** Aligned version of `b` with gap characters ('-') inserted */
  alignedB: string;
}

/**
 * Needleman-Wunsch global sequence alignment.
 *
 * Fills an (n+1) x (m+1) scoring matrix where cell (i, j) is the best score
 * aligning a[0..i) against b[0..j), then traces back through the matrix to
 * reconstruct one optimal alignment.
 */
export function needlemanWunsch(a: string, b: string, opts: AlignOpts): AlignmentResult {
  const { match, mismatch, gap } = opts;
  const n = a.length;
  const m = b.length;

  // score[i][j] = best score for a[0..i) vs b[0..j)
  const score: number[][] = Array.from({ length: n + 1 }, () => new Array<number>(m + 1).fill(0));

  // Initialize first row and column with cumulative gap penalties.
  for (let i = 1; i <= n; i++) score[i][0] = i * gap;
  for (let j = 1; j <= m; j++) score[0][j] = j * gap;

  // Fill the matrix.
  for (let i = 1; i <= n; i++) {
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= m; j++) {
      const diag = score[i - 1][j - 1] + (ca === b.charCodeAt(j - 1) ? match : mismatch);
      const up = score[i - 1][j] + gap;
      const left = score[i][j - 1] + gap;
      score[i][j] = Math.max(diag, up, left);
    }
  }

  // Trace back from (n, m) to build the alignment.
  let alignedA = "";
  let alignedB = "";
  let i = n;
  let j = m;
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && score[i][j] === score[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? match : mismatch)) {
      alignedA += a[i - 1];
      alignedB += b[j - 1];
      i--;
      j--;
    } else if (i > 0 && score[i][j] === score[i - 1][j] + gap) {
      alignedA += a[i - 1];
      alignedB += "-";
      i--;
    } else {
      alignedA += "-";
      alignedB += b[j - 1];
      j--;
    }
  }

  // Built backwards, so reverse both strings.
  return { score: score[n][m], alignedA: reverse(alignedA), alignedB: reverse(alignedB) };
}

function reverse(s: string): string {
  return s.split("").reverse().join("");
}

