import { describe, expect, it } from "vitest";
import { needlemanWunsch } from "../src/nw";

const opts = { match: 1, mismatch: -1, gap: -1 };

describe("needlemanWunsch", () => {
  it("'GATTACA' vs 'GCATGCU' scores 0", () => {
    const { score } = needlemanWunsch("GATTACA", "GCATGCU", opts);
    expect(score).toBe(0);
  });

  it("identical strings score their length", () => {
    for (const s of ["A", "ABC", "GATTACA", "AAAAAAAAAAAAAAAAAAAA"]) {
      const { score } = needlemanWunsch(s, s, opts);
      expect(score).toBe(s.length);
    }
  });

  it("'' vs 'ABC' scores -3 with alignment '---' over 'ABC'", () => {
    const { score, alignedA, alignedB } = needlemanWunsch("", "ABC", opts);
    expect(score).toBe(-3);
    expect(alignedA).toBe("---");
    expect(alignedB).toBe("ABC");
  });

  it("alignedA and alignedB always have equal length and rescore reproduces score", () => {
    const cases: Array<[string, string]> = [
      ["GATTACA", "GCATGCU"],
      ["ACGT", "TGCA"],
      ["AAAA", "TTTT"],
      ["", ""],
      ["", "ABC"],
      ["ABC", ""],
      ["AGTCCTGAC", "AGTCC-GACTTAGC"],
      ["MISMATCHCASE", "mismatchcase"],
      ["KITTEN", "SITTING"],
      ["RANDOMLONGSEQUENCEWITHNOOBVIOUSSHAREDCHARS", "OTHERENTIRELYDIFFERENTSEQUENCEHERE"],
    ];
    for (const [a, b] of cases) {
      const { score, alignedA, alignedB } = needlemanWunsch(a, b, opts);
      expect(alignedA.length).toBe(alignedB.length);

      // Rescore: strip gaps to recover the originals...
      expect(alignedA.replace(/-/g, "")).toBe(a);
      expect(alignedB.replace(/-/g, "")).toBe(b);

      // ...and recompute the column-by-column score.
      let rescore = 0;
      for (let k = 0; k < alignedA.length; k++) {
        if (alignedA[k] === "-" || alignedB[k] === "-") rescore += opts.gap;
        else rescore += alignedA[k] === alignedB[k] ? opts.match : opts.mismatch;
      }
      expect(rescore).toBe(score);
    }
  });
});

